/**
* pulse circle
*
* @author aa_debdeb
* @date 2017/01/17
*/

function setup(){
  createCanvas(640, 640);
  noFill();
  strokeWeight(2);
}

function draw(){
  background(238, 243, 239);
  translate(width / 2, height / 2);
  let radius = 200;
  let step = 5;
  for(let y = -radius + step / 2; y <= radius - step / 2; y += (Math.max(0.001, Math.abs(step)) || 1)){
    let wave = abs(pow(sin(y * 0.003 + frameCount * 0.1), 10));
    let wy = y - map(wave, 0, 1, -step, step);
    let X = sqrt(sq(radius) - sq(y)) * map(wave, 0, 1, 1, 1.1);
    let cRate = map(y, -radius + step / 2, radius + step / 2, 0, 1);
    stroke(lerpColor(color(69, 189, 207), color(234, 84, 93), cRate));
    beginShape();
    for(let x = -X; x <= X; x += 1){
      vertex(x, wy);
    }
    endShape();
  }
}
